-- Food composition: the 528 raw foods of the ICMR-NIN Indian Food Composition
-- Tables 2017, per 100 g edible portion.
--
-- WHY THIS EXISTS
--
-- The clinic's dietitian brief says every macro and micro value on a diet chart
-- must come from IFCT and that there is "no tolerance for errors in calorie or
-- macro totals". Numbers typed by hand — or generated by a language model —
-- cannot honour that: both are recall, not lookup. With the table here, the app
-- CALCULATES a chart's numbers and the ±40 kcal interchangeability rule becomes
-- arithmetic instead of judgement.
--
-- WHAT IS AND ISN'T HERE
--
-- Raw ingredients only. IFCT samples each food across six regions of India, and
-- these are the means. A chart says "1 medium puttu", not "80 g raw rice" — the
-- bridge from one to the other is `dishes` below.
--
-- Energy is converted from IFCT's kilojoules to kilocalories (÷ 4.184).
-- Carbohydrate and fibre are null for meat, fish, eggs and oils, which contain
-- neither; that is absence, not a missing reading.
--
-- SOURCE AND PERMISSION
--
-- Indian Food Composition Tables 2017, ICMR-National Institute of Nutrition,
-- Hyderabad. Reproduced with NIN's permission — see the clinic's records. The
-- `food_code` on every row is IFCT's own, so any value can be traced back to
-- the published table it came from.

create table if not exists foods (
  food_code   text primary key,          -- IFCT's own code, e.g. A001
  name        text not null,
  food_group  text,
  regions     int,                       -- how many of the six regions were sampled
  protein_g   numeric,                   -- all values per 100 g edible portion
  fat_g       numeric,
  carb_g      numeric,
  fibre_g     numeric,
  kcal        numeric,
  source      text not null default 'IFCT 2017',
  created_at  timestamptz not null default now()
);

create index if not exists foods_name_idx on foods (lower(name));
create index if not exists foods_group_idx on foods (food_group);

alter table foods enable row level security;
drop policy if exists foods_read on foods;
-- Reference data, not client data: any signed-in member of staff may read it.
create policy foods_read on foods for select using (is_staff());
drop policy if exists foods_write on foods;
create policy foods_write on foods for all using (is_admin()) with check (is_admin());

on conflict (food_code) do update set
  name = excluded.name, food_group = excluded.food_group, regions = excluded.regions,
  protein_g = excluded.protein_g, fat_g = excluded.fat_g, carb_g = excluded.carb_g,
  fibre_g = excluded.fibre_g, kcal = excluded.kcal;
